import fmt;
import io;

type Point = struct {
    x: i32,
    y: i32,
}

fn dist2(a: Point, b: Point) -> i32 {
    let dx: i32 = a.x - b.x;
    let dy: i32 = a.y - b.y;
    return dx * dx + dy * dy;
}

fn main_jhyy() -> i32 {
    // ⚠️ 字段值要**显式带类型** —— 整数字面量默认是 i32
    let p: Point = Point { x: 10 as i32, y: 20 as i32 };
    let q: Point = Point { x: 1 as i32, y: 2 as i32 };
    let d: i32 = dist2(p, q);
    let mut buf: [u8; 32] = [0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8,
                              0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8,
                              0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8,
                              0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8];
    let out: *u8 = &buf[0];
    let n = fmt_i32(out, d);
    buf[n] = 10u8;
    buf[n + 1i64] = 0u8;
    std_io_print(out);
    return 0;
}

